import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';

import 'package:nothingness/models/audio_track.dart';

import '../dev/main_test.dart' as app;
import '../dev/test_harness.dart';
import '../dev/test_overlay.dart';

Future<void> _pumpUntil(
  WidgetTester tester,
  bool Function() condition, {
  Duration timeout = const Duration(seconds: 3),
  Duration step = const Duration(milliseconds: 50),
}) async {
  final deadline = DateTime.now().add(timeout);
  while (DateTime.now().isBefore(deadline)) {
    await tester.pump(step);
    if (condition()) return;
  }
  throw TestFailure('Condition not met within ${timeout.inMilliseconds}ms');
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  group('smoke: play/pause, skip, and seek', () {
    setUp(() {
      TestHarness.instance.reset();
    });

    testWidgets('smoke: play/pause, skip (next), and seek forward', (tester) async {
      await app.main();
      await tester.pumpAndSettle();

      final h = TestHarness.instance;

      // Initialize a small queue
      await h.setQueue([
        const AudioTrack(path: '/t0.mp3', title: 't0'),
        const AudioTrack(path: '/t1.mp3', title: 't1'),
      ]);
      await tester.pumpAndSettle();

      // Wait for initial playing to start via UI state
      await _pumpUntil(tester, () {
        return find.textContaining('playing=true').evaluate().isNotEmpty;
      });

      // Pause via UI play/pause button
      await tester.tap(find.byKey(TestKeys.playPause));
      await tester.pumpAndSettle();
      expect(find.textContaining('playing=false'), findsOneWidget);

      // Resume via UI play/pause button
      await tester.tap(find.byKey(TestKeys.playPause));
      await tester.pumpAndSettle();
      expect(find.textContaining('playing=true'), findsOneWidget);

      // Skip to next track
      await tester.tap(find.byKey(TestKeys.next));
      await tester.pumpAndSettle();
      expect(find.textContaining('idx=1'), findsOneWidget);

      // Fast-forward: use the controller to seek forward a bit
      final ctrl = h.controller;
      if (ctrl != null) {
        await ctrl.seek(const Duration(seconds: 5));
      }
      await tester.pump(const Duration(milliseconds: 200));
    });
  });
}

